{
  "name": "e-Punch Card Harian",
  "description": "Aplikasi rekod kehadiran harian (Masuk/Keluar) dengan analisis kehadiran pintar menggunakan Gemini AI."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface PunchRecord {
  date: string; // YYYY-MM-DD
  inTime: string | null; // HH:mm format
  outTime: string | null; // HH:mm format
  note?: string;
}

export enum AttendanceStatus {
  PRESENT = 'Hadir',
  ABSENT = 'Tidak Hadir',
  INCOMPLETE = 'Belum Lengkap',
  WEEKEND = 'Hujung Minggu'
}

export interface MonthlyStats {
  totalDays: number;
  presentDays: number;
  totalHours: number;
  lateArrivals: number; // Assuming 9:00 AM is late
}

import { GoogleGenAI } from "@google/genai";
import { PunchRecord } from "../types";

const apiKey = process.env.API_KEY || '';

// Initialize Gemini Client
const ai = new GoogleGenAI({ apiKey });

export const analyzeAttendance = async (records: PunchRecord[], monthName: string): Promise<string> => {
  if (!apiKey) {
    return "API Key tidak ditemui. Sila pastikan API key telah dikonfigurasi.";
  }

  try {
    // Prepare data for the prompt
    const dataSummary = JSON.stringify(records.filter(r => r.inTime || r.outTime));

    const prompt = `
      Anda adalah pembantu HR yang bijak. Sila analisa rekod kehadiran pekerja ini untuk bulan ${monthName}.

      Data Kehadiran (JSON):
      ${dataSummary}

      Sila berikan laporan ringkas dalam Bahasa Melayu yang merangkumi:
      1. Rumusan kehadiran (berapa hari bekerja, purata jam bekerja).
      2. Corak kehadiran (adakah sering lewat? Nota: Lewat dikira selepas 9:00 AM).
      3. Cadangan penambahbaikan atau kata-kata semangat.

      Gunakan format Markdown untuk output. Pastikan nada profesional tetapi mesra.
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        thinkingConfig: { thinkingBudget: 0 } // Disable thinking for faster simple text response
      }
    });

    return response.text || "Tiada analisis dapat dijana.";

  } catch (error) {
    console.error("Error analyzing attendance:", error);
    return "Maaf, berlaku ralat semasa menjana analisis AI. Sila cuba lagi.";
  }
};

import React from 'react';

interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'danger' | 'success';
  isLoading?: boolean;
}

export const Button: React.FC<ButtonProps> = ({ 
  children, 
  variant = 'primary', 
  isLoading = false, 
  className = '', 
  disabled,
  ...props 
}) => {

  const baseStyles = "inline-flex items-center justify-center px-4 py-2 border text-sm font-medium rounded-md focus:outline-none focus:ring-2 focus:ring-offset-2 transition-colors duration-200";

  const variants = {
    primary: "border-transparent text-white bg-indigo-600 hover:bg-indigo-700 focus:ring-indigo-500",
    secondary: "border-gray-300 text-gray-700 bg-white hover:bg-gray-50 focus:ring-indigo-500",
    danger: "border-transparent text-white bg-red-600 hover:bg-red-700 focus:ring-red-500",
    success: "border-transparent text-white bg-green-600 hover:bg-green-700 focus:ring-green-500",
  };

  return (
    <button
      disabled={disabled || isLoading}
      className={`${baseStyles} ${variants[variant]} ${disabled || isLoading ? 'opacity-50 cursor-not-allowed' : ''} ${className}`}
      {...props}
    >
      {isLoading ? (
        <>
          <svg className="animate-spin -ml-1 mr-2 h-4 w-4 text-current" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
            <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
            <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
          </svg>
          Memproses...
        </>
      ) : children}
    </button>
  );
};

