import React from 'react';
import { PunchRecord } from '../types';

interface PunchTableProps {
  records: PunchRecord[];
  currentMonth: Date;
  onEdit: (date: string, type: 'inTime' | 'outTime', value: string) => void;
}

export const PunchTable: React.FC<PunchTableProps> = ({ records, currentMonth, onEdit }) => {
  // Helper to calculate duration
  const calculateDuration = (inTime: string | null, outTime: string | null) => {
    if (!inTime || !outTime) return '-';
    const [inH, inM] = inTime.split(':').map(Number);
    const [outH, outM] = outTime.split(':').map(Number);

    let diffMinutes = (outH * 60 + outM) - (inH * 60 + inM);
    if (diffMinutes < 0) return '-'; // Invalid time range

    const hours = Math.floor(diffMinutes / 60);
    const minutes = diffMinutes % 60;
    return `${hours}j ${minutes}m`;
  };

  // Helper to determine status color
  const getStatusColor = (record: PunchRecord, isWeekend: boolean) => {
    if (isWeekend) return 'bg-gray-100 text-gray-400';
    if (record.inTime && record.outTime) return 'bg-green-100 text-green-800';
    if (record.inTime) return 'bg-yellow-100 text-yellow-800';
    return 'bg-red-50 text-red-500';
  };

  const getStatusText = (record: PunchRecord, isWeekend: boolean) => {
    if (isWeekend) return 'Cuti';
    if (record.inTime && record.outTime) return 'Lengkap';
    if (record.inTime) return 'Masuk';
    return 'Tiada';
  };

  const daysInMonth = new Date(currentMonth.getFullYear(), currentMonth.getMonth() + 1, 0).getDate();

  // Generate array of all days in month
  const allDays = Array.from({ length: daysInMonth }, (_, i) => {
    const day = i + 1;
    const dateObj = new Date(currentMonth.getFullYear(), currentMonth.getMonth(), day);
    const dateStr = `${currentMonth.getFullYear()}-${String(currentMonth.getMonth() + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
    const record = records.find(r => r.date === dateStr) || { date: dateStr, inTime: null, outTime: null };
    const isWeekend = dateObj.getDay() === 0 || dateObj.getDay() === 6; // Sunday(0) or Saturday(6)

    return { day, dateStr, record, isWeekend, dateObj };
  });

  const dayNames = ['Ahad', 'Isnin', 'Selasa', 'Rabu', 'Khamis', 'Jumaat', 'Sabtu'];

  return (
    <div className="flex flex-col mt-6">
      <div className="-my-2 overflow-x-auto sm:-mx-6 lg:-mx-8">
        <div className="py-2 align-middle inline-block min-w-full sm:px-6 lg:px-8">
          <div className="shadow overflow-hidden border-b border-gray-200 sm:rounded-lg">
            <table className="min-w-full divide-y divide-gray-200">
              <thead className="bg-gray-50">
                <tr>
                  <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                    Tarikh
                  </th>
                  <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                    Hari
                  </th>
                  <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                    Masuk (IN)
                  </th>
                  <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                    Keluar (OUT)
                  </th>
                  <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                    Tempoh
                  </th>
                  <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                    Status
                  </th>
                </tr>
              </thead>
              <tbody className="bg-white divide-y divide-gray-200">
                {allDays.map(({ day, dateStr, record, isWeekend, dateObj }) => (
                  <tr key={dateStr} className={isWeekend ? "bg-gray-50" : "hover:bg-gray-50"}>
                    <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-gray-900">
                      {day}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                      {dayNames[dateObj.getDay()]}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                      <input 
                        type="time" 
                        value={record.inTime || ''} 
                        onChange={(e) => onEdit(dateStr, 'inTime', e.target.value)}
                        className={`border-gray-300 rounded-md text-sm focus:ring-indigo-500 focus:border-indigo-500 ${isWeekend ? 'bg-gray-50' : ''}`}
                        disabled={false} // Always allow edits for flexibility
                      />
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                      <input 
                        type="time" 
                        value={record.outTime || ''} 
                        onChange={(e) => onEdit(dateStr, 'outTime', e.target.value)}
                        className={`border-gray-300 rounded-md text-sm focus:ring-indigo-500 focus:border-indigo-500 ${isWeekend ? 'bg-gray-50' : ''}`}
                      />
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                      {calculateDuration(record.inTime, record.outTime)}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <span className={`px-2 inline-flex text-xs leading-5 font-semibold rounded-full ${getStatusColor(record, isWeekend)}`}>
                        {getStatusText(record, isWeekend)}
                      </span>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useCallback } from 'react';
import { Button } from './components/Button';
import { PunchTable } from './components/PunchTable';
import { StatCard } from './components/StatCard';
import { analyzeAttendance } from './services/geminiService';
import { PunchRecord } from './types';
import Markdown from 'react-markdown';

// Icons
const ClockIcon = () => <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>;
const CheckCircleIcon = () => <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>;
const CalendarIcon = () => <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg>;
const SparklesIcon = () => <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 3v4M3 5h4M6 17v4m-2-2h4m5-16l2.286 6.857L21 12l-5.714 2.143L13 21l-2.286-6.857L5 12l5.714-2.143L13 3z" /></svg>;

function App() {
  // State
  const [currentMonth, setCurrentMonth] = useState(new Date());
  const [records, setRecords] = useState<PunchRecord[]>([]);
  const [currentTime, setCurrentTime] = useState(new Date());

  // AI State
  const [analysis, setAnalysis] = useState<string | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [showAnalysisModal, setShowAnalysisModal] = useState(false);

  // Load records from local storage on mount
  useEffect(() => {
    const saved = localStorage.getItem('punchRecords');
    if (saved) {
      try {
        setRecords(JSON.parse(saved));
      } catch (e) {
        console.error("Failed to parse records", e);
      }
    }
  }, []);

  // Save records when they change
  useEffect(() => {
    localStorage.setItem('punchRecords', JSON.stringify(records));
  }, [records]);

  // Clock Ticker
  useEffect(() => {
    const timer = setInterval(() => setCurrentTime(new Date()), 1000);
    return () => clearInterval(timer);
  }, []);

  const getTodayStr = () => currentTime.toISOString().split('T')[0];
  const getCurrentTimeStr = () => currentTime.toTimeString().slice(0, 5); // HH:mm

  // Handle Punch In/Out
  const handlePunch = (type: 'IN' | 'OUT') => {
    const todayStr = getTodayStr();
    const timeStr = getCurrentTimeStr();

    setRecords(prev => {
      const existingIndex = prev.findIndex(r => r.date === todayStr);
      let newRecords = [...prev];

      if (existingIndex >= 0) {
        // Update existing record
        newRecords[existingIndex] = {
          ...newRecords[existingIndex],
          inTime: type === 'IN' ? timeStr : newRecords[existingIndex].inTime,
          outTime: type === 'OUT' ? timeStr : newRecords[existingIndex].outTime,
        };
      } else {
        // Create new record
        newRecords.push({
          date: todayStr,
          inTime: type === 'IN' ? timeStr : null,
          outTime: type === 'OUT' ? timeStr : null,
        });
      }
      return newRecords;
    });
  };

  // Handle Manual Edits from Table
  const handleEdit = (date: string, type: 'inTime' | 'outTime', value: string) => {
    setRecords(prev => {
      const existingIndex = prev.findIndex(r => r.date === date);
      let newRecords = [...prev];

      if (existingIndex >= 0) {
        newRecords[existingIndex] = {
          ...newRecords[existingIndex],
          [type]: value || null
        };
      } else {
        newRecords.push({
          date: date,
          inTime: type === 'inTime' ? value : null,
          outTime: type === 'outTime' ? value : null,
        });
      }
      return newRecords;
    });
  };

  // Month Navigation
  const changeMonth = (offset: number) => {
    const newDate = new Date(currentMonth.getFullYear(), currentMonth.getMonth() + offset, 1);
    setCurrentMonth(newDate);
  };

  // Filter records for current month only
  const getMonthRecords = () => {
    const year = currentMonth.getFullYear();
    const month = currentMonth.getMonth() + 1;
    return records.filter(r => {
      const [rYear, rMonth] = r.date.split('-').map(Number);
      return rYear === year && rMonth === month;
    });
  };

  // Get Today's Status
  const todayRecord = records.find(r => r.date === getTodayStr());
  const hasPunchedIn = !!todayRecord?.inTime;
  const hasPunchedOut = !!todayRecord?.outTime;

  // AI Analysis Handler
  const handleAnalyze = async () => {
    setIsAnalyzing(true);
    setShowAnalysisModal(true);

    const monthName = currentMonth.toLocaleDateString('ms-MY', { month: 'long', year: 'numeric' });
    const result = await analyzeAttendance(getMonthRecords(), monthName);

    setAnalysis(result);
    setIsAnalyzing(false);
  };

  return (
    <div className="min-h-screen bg-gray-100 pb-12">
      {/* Header */}
      <header className="bg-indigo-600 shadow-lg">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-6">
          <div className="flex items-center justify-between">
            <h1 className="text-3xl font-bold text-white flex items-center gap-2">
              <CalendarIcon />
              e-Punch Card Harian
            </h1>
            <div className="text-white text-right">
              <div className="text-sm opacity-80">{currentTime.toLocaleDateString('ms-MY', { weekday: 'long', day: 'numeric', month: 'long' })}</div>
              <div className="text-2xl font-mono font-bold">{currentTime.toLocaleTimeString('ms-MY')}</div>
            </div>
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 -mt-8">
        {/* Status Cards / Actions */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8">

          {/* Main Action Card */}
          <div className="md:col-span-2 bg-white rounded-lg shadow-lg p-6 flex flex-col justify-center items-center space-y-4">
             <h2 className="text-lg font-medium text-gray-700">Tindakan Hari Ini</h2>
             <div className="flex gap-4 w-full justify-center">
               <Button 
                variant="success" 
                className="w-40 h-16 text-lg shadow-md"
                onClick={() => handlePunch('IN')}
                disabled={hasPunchedIn}
               >
                 {hasPunchedIn ? 'Sudah Masuk' : 'MASUK (IN)'}
               </Button>
               <Button 
                variant="danger" 
                className="w-40 h-16 text-lg shadow-md"
                onClick={() => handlePunch('OUT')}
                disabled={!hasPunchedIn || hasPunchedOut}
               >
                 {hasPunchedOut ? 'Sudah Keluar' : 'KELUAR (OUT)'}
               </Button>
             </div>
             {hasPunchedIn && !hasPunchedOut && (
               <p className="text-sm text-green-600 font-medium animate-pulse">
                 Anda sedang bekerja. Waktu Masuk: {todayRecord?.inTime}
               </p>
             )}
             {hasPunchedOut && (
               <p className="text-sm text-gray-500">
                 Selesai untuk hari ini. Jam: {todayRecord?.inTime} - {todayRecord?.outTime}
               </p>
             )}
          </div>

          {/* Mini Stats Card */}
          <div className="space-y-4">
             <StatCard 
               title="Hari Bekerja (Bulan Ini)"
               value={getMonthRecords().filter(r => r.inTime && r.outTime).length}
               icon={<CheckCircleIcon />}
               colorClass="bg-blue-100 text-blue-600"
             />
             <div className="bg-indigo-50 rounded-lg p-4 border border-indigo-100 flex items-center justify-between cursor-pointer hover:bg-indigo-100 transition" onClick={handleAnalyze}>
                <div className="flex items-center gap-3">
                  <div className="p-2 bg-indigo-200 rounded-md text-indigo-700"><SparklesIcon /></div>
                  <div>
                    <h3 className="text-sm font-bold text-indigo-900">Analisa AI</h3>
                    <p className="text-xs text-indigo-700">Dapatkan laporan prestasi</p>
                  </div>
                </div>
             </div>
          </div>
        </div>

        {/* Month Navigation & Table */}
        <div className="bg-white shadow rounded-lg p-6">
           <div className="flex items-center justify-between mb-4">
             <button onClick={() => changeMonth(-1)} className="p-2 hover:bg-gray-100 rounded-full">
               <svg className="w-5 h-5 text-gray-600" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" /></svg>
             </button>
             <h2 className="text-xl font-bold text-gray-800 uppercase tracking-wide">
               {currentMonth.toLocaleDateString('ms-MY', { month: 'long', year: 'numeric' })}
             </h2>
             <button onClick={() => changeMonth(1)} className="p-2 hover:bg-gray-100 rounded-full">
               <svg className="w-5 h-5 text-gray-600" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" /></svg>
             </button>
           </div>

           <PunchTable 
             records={records} 
             currentMonth={currentMonth}
             onEdit={handleEdit}
           />
        </div>
      </main>

      {/* AI Analysis Modal */}
      {showAnalysisModal && (
        <div className="fixed inset-0 z-50 overflow-y-auto" aria-labelledby="modal-title" role="dialog" aria-modal="true">
          <div className="flex items-end justify-center min-h-screen pt-4 px-4 pb-20 text-center sm:block sm:p-0">
            <div className="fixed inset-0 bg-gray-500 bg-opacity-75 transition-opacity" onClick={() => setShowAnalysisModal(false)}></div>
            <span className="hidden sm:inline-block sm:align-middle sm:h-screen" aria-hidden="true">&#8203;</span>
            <div className="inline-block align-bottom bg-white rounded-lg text-left overflow-hidden shadow-xl transform transition-all sm:my-8 sm:align-middle sm:max-w-2xl sm:w-full">
              <div className="bg-white px-4 pt-5 pb-4 sm:p-6 sm:pb-4">
                <div className="sm:flex sm:items-start">
                  <div className="mx-auto flex-shrink-0 flex items-center justify-center h-12 w-12 rounded-full bg-indigo-100 sm:mx-0 sm:h-10 sm:w-10">
                    <SparklesIcon />
                  </div>
                  <div className="mt-3 text-center sm:mt-0 sm:ml-4 sm:text-left w-full">
                    <h3 className="text-lg leading-6 font-medium text-gray-900" id="modal-title">
                      Laporan Analisis Kehadiran
                    </h3>
                    <div className="mt-4 text-sm text-gray-600 bg-gray-50 p-4 rounded-md min-h-[100px] max-h-[60vh] overflow-y-auto">
                      {isAnalyzing ? (
                        <div className="flex flex-col items-center justify-center py-8">
                           <svg className="animate-spin h-8 w-8 text-indigo-600 mb-4" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                              <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                              <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                           </svg>
                           <p>Sedang menjana laporan cerdas...</p>
                        </div>
                      ) : (
                        <div className="prose prose-sm prose-indigo">
                           <Markdown>{analysis}</Markdown>
                        </div>
                      )}
                    </div>
                  </div>
                </div>
              </div>
              <div className="bg-gray-50 px-4 py-3 sm:px-6 sm:flex sm:flex-row-reverse">
                <Button variant="primary" onClick={() => setShowAnalysisModal(false)} disabled={isAnalyzing}>
                  Tutup
                </Button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Footer */}
      <footer className="mt-12 text-center text-gray-500 text-sm pb-6">
        <p>&copy; {new Date().getFullYear()} Sistem e-Punch Card Harian.</p>
      </footer>
    </div>
  );
}

export default App;

