import Markdown from 'react-markdown';

// Icons (Updated styles)
const ClockIcon = () => <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>;
const CheckCircleIcon = () => <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>;
const CalendarIcon = () => <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg>;
const SparklesIcon = () => <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 3v4M3 5h4M6 17v4m-2-2h4m5-16l2.286 6.857L21 12l-5.714 2.143L13 21l-2.286-6.857L5 12l5.714-2.143L13 3z" /></svg>;
const DownloadIcon = () => <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>;
const ChatBubbleIcon = () => <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 10h.01M12 10h.01M16 10h.01M9 16H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-5l-5 5v-5z" /></svg>;

function App() {
  // State
  const [currentMonth, setCurrentMonth] = useState(new Date());
  const [records, setRecords] = useState<PunchRecord[]>([]);
  const [currentTime, setCurrentTime] = useState(new Date());

  // AI State
  const [analysis, setAnalysis] = useState<string | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [showAnalysisModal, setShowAnalysisModal] = useState(false);

  // Note Modal State
  const [noteModal, setNoteModal] = useState<{isOpen: boolean, date: string, text: string}>({
    isOpen: false,
    date: '',
    text: ''
  });

  // Load records from local storage on mount
  useEffect(() => {
    const saved = localStorage.getItem('punchRecords');
    if (saved) {
      try {
        setRecords(JSON.parse(saved));
      } catch (e) {
        console.error("Failed to parse records", e);
      }
    }
  }, []);

  // Save records when they change
  useEffect(() => {
    localStorage.setItem('punchRecords', JSON.stringify(records));
  }, [records]);

  // Clock Ticker
  useEffect(() => {
    const timer = setInterval(() => setCurrentTime(new Date()), 1000);
    return () => clearInterval(timer);
  }, []);

  const getTodayStr = () => currentTime.toISOString().split('T')[0];
  const getCurrentTimeStr = () => currentTime.toTimeString().slice(0, 5); // HH:mm

  // Handle Manual Edits from Table (Time and Notes)
  const handleEdit = (date: string, type: 'inTime' | 'outTime' | 'note', value: string) => {
    setRecords(prev => {
      const existingIndex = prev.findIndex(r => r.date === date);
      let newRecords = [...prev];

      if (existingIndex >= 0) {
        newRecords[existingIndex] = {
          ...newRecords[existingIndex],
          [type]: value || null
        };
      } else {
        newRecords.push({
          date: date,
          inTime: type === 'inTime' ? value : (type === 'outTime' ? null : null), // Initialize others as null
          outTime: type === 'outTime' ? value : null,
          note: type === 'note' ? value : undefined
        });
      }
      return newRecords;
    });
  };

  // Note Modal Handlers
  const handleOpenNote = (date: string, currentText: string) => {
    setNoteModal({ isOpen: true, date, text: currentText || '' });
  };

  const handleSaveNote = () => {
    handleEdit(noteModal.date, 'note', noteModal.text);
    setNoteModal({ ...noteModal, isOpen: false });
  };

  // Month Navigation
  const changeMonth = (offset: number) => {
    const newDate = new Date(currentMonth.getFullYear(), currentMonth.getMonth() + offset, 1);
    setCurrentMonth(newDate);
  };

  // Filter records for current month only
  const getMonthRecords = () => {
    const year = currentMonth.getFullYear();
    const month = currentMonth.getMonth() + 1;
    return records.filter(r => {
      const [rYear, rMonth] = r.date.split('-').map(Number);
      return rYear === year && rMonth === month;
    });
  };

  // Calculate Total Hours for the month
  const calculateTotalMonthHours = () => {
    const monthRecords = getMonthRecords();
    let totalMinutes = 0;

    monthRecords.forEach(record => {
      if (record.inTime && record.outTime) {
        const [inH, inM] = record.inTime.split(':').map(Number);
        const [outH, outM] = record.outTime.split(':').map(Number);

        const diff = (outH * 60 + outM) - (inH * 60 + inM);
        if (diff > 0) {
          totalMinutes += diff;
        }
      }
    });

    const hours = Math.floor(totalMinutes / 60);
    const minutes = totalMinutes % 60;

    return `${hours}j ${minutes}m`;
  };

  // Export CSV Handler
  const handleExportCSV = () => {
    const year = currentMonth.getFullYear();
    const month = currentMonth.getMonth();
    const daysInMonth = new Date(year, month + 1, 0).getDate();
    const monthName = currentMonth.toLocaleDateString('ms-MY', { month: 'long', year: 'numeric' });

    const headers = ['Tarikh', 'Hari', 'Masuk (IN)', 'Keluar (OUT)', 'Tempoh', 'Status', 'Catatan'];
    let csvContent = headers.join(',') + '\n';

    for (let i = 1; i <= daysInMonth; i++) {
      const dateObj = new Date(year, month, i);
      const dateStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(i).padStart(2, '0')}`;
      const record = records.find(r => r.date === dateStr) || { date: dateStr, inTime: null, outTime: null, note: '' };

      const formattedDate = dateObj.toLocaleDateString('en-GB', { day: '2-digit', month: '2-digit', year: 'numeric' });
      const dayName = dateObj.toLocaleDateString('ms-MY', { weekday: 'long' });

      // Changed weekend logic: Friday (5) and Saturday (6) are weekends
      const isWeekend = dateObj.getDay() === 5 || dateObj.getDay() === 6;

      // Calculate Status (Replicating PunchTable logic for consistency)
      let status = 'Tiada';
      if (isWeekend) status = 'Cuti';
      else if (record.inTime && record.outTime) status = 'Lengkap';
      else if (record.inTime) status = 'Masuk';

      // Calculate Duration
      let duration = '-';
      if (record.inTime && record.outTime) {
        const [inH, inM] = record.inTime.split(':').map(Number);
        const [outH, outM] = record.outTime.split(':').map(Number);
        let diffMinutes = (outH * 60 + outM) - (inH * 60 + inM);

        if (diffMinutes >= 0) {
          const hours = Math.floor(diffMinutes / 60);
          const minutes = diffMinutes % 60;
          duration = `${hours}j ${minutes}m`;
        }
      }

      // Safe CSV string escaping
      const escapeCsv = (str: string | null | undefined) => {
        if (!str) return '""';
        return `"${str.replace(/"/g, '""')}"`;
      };

      const row = [
        formattedDate,
        dayName,
        record.inTime || '',
        record.outTime || '',
        duration,
        status,
        record.note || ''
      ].map(field => escapeCsv(field)).join(',');

      csvContent += row + '\n';
    }

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    if (link.download !== undefined) {
      const url = URL.createObjectURL(blob);
      link.setAttribute('href', url);
      link.setAttribute('download', `Laporan_Kehadiran_${monthName.replace(/\s+/g, '_')}.csv`);
      link.style.visibility = 'hidden';
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
    }
  };

  // AI Analysis Handler
  const handleAnalyze = async () => {
    setIsAnalyzing(true);
    setShowAnalysisModal(true);

    const monthName = currentMonth.toLocaleDateString('ms-MY', { month: 'long', year: 'numeric' });
    const result = await analyzeAttendance(getMonthRecords(), monthName);

    setAnalysis(result);
    setIsAnalyzing(false);
  };

  return (
    <div 
      className="min-h-screen pb-12 bg-cover bg-center bg-fixed bg-no-repeat"
      style={{
        backgroundImage: `url('https://images.unsplash.com/photo-1614850523459-c2f4c699c52e?q=80&w=2070&auto=format&fit=crop')` // Modern Abstract Gradient
      }}
    >
      {/* Vibrant Header - Kept opaque for contrast */}
      <header className="bg-gradient-to-r from-violet-600/95 via-purple-600/95 to-fuchsia-600/95 backdrop-blur-sm shadow-xl pb-24 relative overflow-hidden">
        {/* Background Pattern */}
        <div className="absolute inset-0 opacity-10 bg-[url('https://www.transparenttextures.com/patterns/cubes.png')]"></div>

        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 relative z-10">
          <div className="flex flex-col md:flex-row items-center justify-between gap-4">
            <h1 className="text-4xl font-extrabold text-white flex items-center gap-3 tracking-tight drop-shadow-sm">
              <div className="bg-white/20 p-2 rounded-xl backdrop-blur-sm">
                <CalendarIcon />
              </div>
              e-Harian
            </h1>
            <div className="text-white text-center md:text-right bg-white/10 px-4 py-2 rounded-xl backdrop-blur-sm border border-white/10">
              <div className="text-sm font-medium opacity-90">{currentTime.toLocaleDateString('ms-MY', { weekday: 'long', day: 'numeric', month: 'long' })}</div>
              <div className="text-3xl font-mono font-bold tracking-wider">{currentTime.toLocaleTimeString('ms-MY')}</div>
            </div>
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 -mt-20 relative z-20">
        {/* Status Cards / Actions */}
        <div className="mb-8">
          {/* Stats Card - More vibrant color */}
          <StatCard 
            title="Jumlah Jam (Bulan Ini)"
            value={calculateTotalMonthHours()}
            icon={<ClockIcon />}
            colorClass="bg-sky-100 text-sky-600"
          />
        </div>

        {/* Month Navigation & Table - Glassmorphism Effect */}
        <div className="bg-white/95 backdrop-blur-sm shadow-lg shadow-gray-200/50 rounded-2xl p-6 border border-white/40">
           <div className="flex flex-col sm:flex-row items-center justify-between mb-8 gap-4">
             {/* Left: Spacer */}
             <div className="hidden sm:block sm:w-1/3"></div>

             {/* Center: Month Navigation */}
             <div className="flex items-center justify-center space-x-6 sm:w-1/3 bg-gray-50/80 p-2 rounded-full border border-gray-200/60 backdrop-blur-sm">
                <button onClick={() => changeMonth(-1)} className="p-2 hover:bg-white hover:shadow-sm rounded-full transition-all text-gray-500 hover:text-violet-600">
                  <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M15 19l-7-7 7-7" /></svg>
                </button>
                <h2 className="text-lg font-bold text-gray-800 uppercase tracking-wide whitespace-nowrap min-w-[150px] text-center">
                  {currentMonth.toLocaleDateString('ms-MY', { month: 'long', year: 'numeric' })}
                </h2>
                <button onClick={() => changeMonth(1)} className="p-2 hover:bg-white hover:shadow-sm rounded-full transition-all text-gray-500 hover:text-violet-600">
                  <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M9 5l7 7-7 7" /></svg>
                </button>
             </div>

             {/* Right: Actions */}
             <div className="flex flex-col sm:flex-row justify-end sm:w-1/3 w-full gap-2">
                <Button 
                   variant="primary" 
                   onClick={handleAnalyze} 
                   className="w-full sm:w-auto !px-4 flex items-center justify-center" 
                   title="Analisa Prestasi (AI)"
                >
                   <SparklesIcon />
                </Button>

                <Button variant="secondary" onClick={handleExportCSV} className="w-full sm:w-auto flex items-center justify-center gap-2 border-gray-200/80 bg-white/80 backdrop-blur-sm hover:bg-white" title="Muat Turun CSV">
                   <DownloadIcon />
                   <span>CSV</span>
                </Button>
             </div>
           </div>

           <PunchTable 
             records={records} 
             currentMonth={currentMonth}
             onEdit={handleEdit}
             onEditNote={handleOpenNote}
           />
        </div>
      </main>

      {/* AI Analysis Modal */}
      {showAnalysisModal && (
        <div className="fixed inset-0 z-50 overflow-y-auto" aria-labelledby="modal-title" role="dialog" aria-modal="true">
          <div className="flex items-end justify-center min-h-screen pt-4 px-4 pb-20 text-center sm:block sm:p-0">
            <div className="fixed inset-0 bg-gray-900 bg-opacity-60 backdrop-blur-sm transition-opacity" onClick={() => setShowAnalysisModal(false)}></div>
            <span className="hidden sm:inline-block sm:align-middle sm:h-screen" aria-hidden="true">&#8203;</span>
            <div className="inline-block align-bottom bg-white rounded-2xl text-left overflow-hidden shadow-2xl transform transition-all sm:my-8 sm:align-middle sm:max-w-2xl sm:w-full border border-gray-100">
              <div className="bg-white px-4 pt-5 pb-4 sm:p-8">
                <div className="sm:flex sm:items-start">
                  <div className="mx-auto flex-shrink-0 flex items-center justify-center h-12 w-12 rounded-full bg-violet-100 sm:mx-0 sm:h-14 sm:w-14">
                    <div className="text-violet-600">
                      <SparklesIcon />
                    </div>
                  </div>
                  <div className="mt-4 text-center sm:mt-0 sm:ml-6 sm:text-left w-full">
                    <h3 className="text-xl leading-6 font-bold text-gray-900" id="modal-title">
                      Laporan Keseluruhan Bulanan
                    </h3>
                    <div className="mt-4 text-sm text-gray-600 bg-slate-50 p-6 rounded-xl border border-slate-100 min-h-[100px] max-h-[60vh] overflow-y-auto shadow-inner">
                      {isAnalyzing ? (
                        <div className="flex flex-col items-center justify-center py-10">
                           <div className="relative">
                             <div className="w-12 h-12 rounded-full border-4 border-violet-100 animate-spin border-t-violet-600"></div>
                           </div>
                           <p className="mt-4 font-medium text-violet-600 animate-pulse">Sedang menjana laporan cerdas...</p>
                        </div>
                      ) : (
