const ChatBubbleIcon = () => <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 10h.01M12 10h.01M16 10h.01M9 16H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-5l-5 5v-5z" /></svg>;

function App() {
  // State
  const [currentMonth, setCurrentMonth] = useState(new Date());
  const [records, setRecords] = useState<PunchRecord[]>([]);
  const [currentTime, setCurrentTime] = useState(new Date());

  // AI State
  const [analysis, setAnalysis] = useState<string | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [showAnalysisModal, setShowAnalysisModal] = useState(false);

  // Note Modal State
  const [noteModal, setNoteModal] = useState<{isOpen: boolean, date: string, text: string}>({
    isOpen: false,
    date: '',
    text: ''
  });

  // Load records from local storage on mount
  useEffect(() => {
    const saved = localStorage.getItem('punchRecords');
    if (saved) {
      try {
        setRecords(JSON.parse(saved));
      } catch (e) {
        console.error("Failed to parse records", e);
      }
    }
  }, []);

  // Save records when they change
  useEffect(() => {
    localStorage.setItem('punchRecords', JSON.stringify(records));
  }, [records]);

  // Clock Ticker
  useEffect(() => {
    const timer = setInterval(() => setCurrentTime(new Date()), 1000);
    return () => clearInterval(timer);
  }, []);

  const getTodayStr = () => currentTime.toISOString().split('T')[0];
  const getCurrentTimeStr = () => currentTime.toTimeString().slice(0, 5); // HH:mm

  // Handle Manual Edits from Table (Time and Notes)
  const handleEdit = (date: string, type: 'inTime' | 'outTime' | 'note', value: string) => {
    setRecords(prev => {
      const existingIndex = prev.findIndex(r => r.date === date);
      let newRecords = [...prev];

      if (existingIndex >= 0) {
        newRecords[existingIndex] = {
          ...newRecords[existingIndex],
          [type]: value || null
        };
      } else {
        newRecords.push({
          date: date,
          inTime: type === 'inTime' ? value : (type === 'outTime' ? null : null), // Initialize others as null
          outTime: type === 'outTime' ? value : null,
          note: type === 'note' ? value : undefined
        });
      }
      return newRecords;
    });
  };

  // Note Modal Handlers
  const handleOpenNote = (date: string, currentText: string) => {
    setNoteModal({ isOpen: true, date, text: currentText || '' });
  };

  const handleSaveNote = () => {
    handleEdit(noteModal.date, 'note', noteModal.text);
    setNoteModal({ ...noteModal, isOpen: false });
  };

  // Month Navigation
  const changeMonth = (offset: number) => {
    const newDate = new Date(currentMonth.getFullYear(), currentMonth.getMonth() + offset, 1);
    setCurrentMonth(newDate);
  };

  // Filter records for current month only
  const getMonthRecords = () => {
    const year = currentMonth.getFullYear();
    const month = currentMonth.getMonth() + 1;
    return records.filter(r => {
      const [rYear, rMonth] = r.date.split('-').map(Number);
      return rYear === year && rMonth === month;
    });
  };

  // Calculate Total Hours for the month
  const calculateTotalMonthHours = () => {
    const monthRecords = getMonthRecords();
    let totalMinutes = 0;

    monthRecords.forEach(record => {
      if (record.inTime && record.outTime) {
        const [inH, inM] = record.inTime.split(':').map(Number);
        const [outH, outM] = record.outTime.split(':').map(Number);

        const diff = (outH * 60 + outM) - (inH * 60 + inM);
        if (diff > 0) {
          totalMinutes += diff;
        }
      }
    });

    const hours = Math.floor(totalMinutes / 60);
    const minutes = totalMinutes % 60;

    return `${hours}j ${minutes}m`;
  };

  // Export CSV Handler
  const handleExportCSV = () => {
    const year = currentMonth.getFullYear();
    const month = currentMonth.getMonth();
    const daysInMonth = new Date(year, month + 1, 0).getDate();
    const monthName = currentMonth.toLocaleDateString('ms-MY', { month: 'long', year: 'numeric' });

    const headers = ['Tarikh', 'Hari', 'Masuk (IN)', 'Keluar (OUT)', 'Tempoh', 'Status', 'Catatan'];
    let csvContent = headers.join(',') + '\n';

    for (let i = 1; i <= daysInMonth; i++) {
      const dateObj = new Date(year, month, i);
      const dateStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(i).padStart(2, '0')}`;
      const record = records.find(r => r.date === dateStr) || { date: dateStr, inTime: null, outTime: null, note: '' };

      const formattedDate = dateObj.toLocaleDateString('en-GB', { day: '2-digit', month: '2-digit', year: 'numeric' });
      const dayName = dateObj.toLocaleDateString('ms-MY', { weekday: 'long' });

      // Changed weekend logic: Friday (5) and Saturday (6) are weekends
      const isWeekend = dateObj.getDay() === 5 || dateObj.getDay() === 6;

      // Calculate Status (Replicating PunchTable logic for consistency)
      let status = 'Tiada';
      if (isWeekend) status = 'Cuti';
      else if (record.inTime && record.outTime) status = 'Lengkap';
      else if (record.inTime) status = 'Masuk';

      // Calculate Duration
      let duration = '-';
      if (record.inTime && record.outTime) {
        const [inH, inM] = record.inTime.split(':').map(Number);
        const [outH, outM] = record.outTime.split(':').map(Number);
        let diffMinutes = (outH * 60 + outM) - (inH * 60 + inM);

        if (diffMinutes >= 0) {
          const hours = Math.floor(diffMinutes / 60);
          const minutes = diffMinutes % 60;
          duration = `${hours}j ${minutes}m`;
        }
      }

      // Safe CSV string escaping
      const escapeCsv = (str: string | null | undefined) => {
        if (!str) return '""';
        return `"${str.replace(/"/g, '""')}"`;
      };

      const row = [
        formattedDate,
        dayName,
        record.inTime || '',
        record.outTime || '',
        duration,
        status,
        record.note || ''
      ].map(field => escapeCsv(field)).join(',');

      csvContent += row + '\n';
    }

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    if (link.download !== undefined) {
      const url = URL.createObjectURL(blob);
      link.setAttribute('href', url);
      link.setAttribute('download', `Laporan_Kehadiran_${monthName.replace(/\s+/g, '_')}.csv`);
      link.style.visibility = 'hidden';
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
    }
  };

  // AI Analysis Handler
  const handleAnalyze = async () => {
    setIsAnalyzing(true);
    setShowAnalysisModal(true);

    const monthName = currentMonth.toLocaleDateString('ms-MY', { month: 'long', year: 'numeric' });
    const result = await analyzeAttendance(getMonthRecords(), monthName);

    setAnalysis(result);
    setIsAnalyzing(false);
  };

  return (
    <div 
      className="min-h-screen pb-12 bg-cover bg-center bg-fixed bg-no-repeat font-sans"
      style={{
        backgroundImage: `url('https://images.unsplash.com/photo-1620641788421-7f1c91ade639?q=80&w=2560&auto=format&fit=crop')` // Stunning Seamless Gradient
      }}
    >
      {/* 
         Unified Header Concept: 
         Instead of a full-width background bar, we use transparency so the wallpaper flows through.
         Content is contained in glass capsules.
      */}
      <header className="pt-8 pb-32 relative z-10">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex flex-col md:flex-row items-center justify-between gap-6">

            {/* Logo / Title Area */}
            <div className="bg-white/10 backdrop-blur-md border border-white/20 rounded-2xl p-4 shadow-xl flex items-center gap-4 hover:bg-white/15 transition-colors duration-300">
               <div className="bg-gradient-to-br from-violet-500 to-fuchsia-500 p-3 rounded-xl shadow-lg">
                 <CalendarIcon />
               </div>
               <div>
                  <h1 className="text-2xl font-bold text-white tracking-tight drop-shadow-sm leading-none">e-Harian</h1>
                  <span className="text-xs text-blue-100 font-medium tracking-wider uppercase">Sistem Kehadiran</span>
               </div>
            </div>

            {/* Clock Area */}
            <div className="flex flex-col items-center md:items-end">
               <div className="bg-black/20 backdrop-blur-md rounded-2xl px-6 py-3 border border-white/10 shadow-lg text-white">
                  <div className="text-xs font-medium text-blue-200 uppercase tracking-widest text-center mb-1">
                    {currentTime.toLocaleDateString('ms-MY', { weekday: 'long', day: 'numeric', month: 'long' })}
                  </div>
                  <div className="text-4xl font-mono font-bold tracking-wider drop-shadow-lg text-center">
                    {currentTime.toLocaleTimeString('ms-MY')}
                  </div>
               </div>
            </div>

          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 -mt-24 relative z-20">
        {/* Status Cards / Actions */}
        <div className="mb-8 transform transition-all hover:scale-[1.01] duration-300">
          {/* Stats Card - Enhanced Glassmorphism */}
          <StatCard 
            title="Jumlah Jam (Bulan Ini)"
            value={calculateTotalMonthHours()}
            icon={<ClockIcon />}
            colorClass="bg-gradient-to-br from-cyan-400 to-blue-500 text-white shadow-lg"
          />
        </div>

        {/* Month Navigation & Table - Glassmorphism Effect */}
        <div className="bg-white/90 backdrop-blur-lg shadow-2xl shadow-black/5 rounded-3xl p-1 border border-white/60">
           <div className="bg-white/50 rounded-[1.4rem] p-6">
              <div className="flex flex-col sm:flex-row items-center justify-between mb-8 gap-4">
                {/* Left: Spacer */}
                <div className="hidden sm:block sm:w-1/3"></div>

                {/* Center: Month Navigation */}
                <div className="flex items-center justify-center space-x-6 sm:w-1/3 bg-white p-2 rounded-full border border-gray-100 shadow-sm">
                    <button onClick={() => changeMonth(-1)} className="p-2.5 hover:bg-gray-50 rounded-full transition-all text-gray-400 hover:text-violet-600">
                      <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M15 19l-7-7 7-7" /></svg>
                    </button>
                    <h2 className="text-lg font-bold text-gray-800 uppercase tracking-wide whitespace-nowrap min-w-[150px] text-center">
                      {currentMonth.toLocaleDateString('ms-MY', { month: 'long', year: 'numeric' })}
                    </h2>
                    <button onClick={() => changeMonth(1)} className="p-2.5 hover:bg-gray-50 rounded-full transition-all text-gray-400 hover:text-violet-600">
                      <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M9 5l7 7-7 7" /></svg>
                    </button>
                </div>

                {/* Right: Actions */}
                <div className="flex flex-col sm:flex-row justify-end sm:w-1/3 w-full gap-2">
                    <Button 
                      variant="primary" 
                      onClick={handleAnalyze} 
                      className="w-full sm:w-auto !px-4 flex items-center justify-center !rounded-full shadow-lg shadow-violet-500/30" 
                      title="Analisa Prestasi (AI)"
                    >
                      <SparklesIcon />
                    </Button>

                    <Button variant="secondary" onClick={handleExportCSV} className="w-full sm:w-auto flex items-center justify-center gap-2 border-gray-200 !rounded-full hover:bg-gray-50" title="Muat Turun CSV">
                      <DownloadIcon />
                      <span>CSV</span>
                    </Button>
                </div>
              </div>

              <PunchTable 
                records={records} 
                currentMonth={currentMonth}
                onEdit={handleEdit}
                onEditNote={handleOpenNote}
              />
           </div>
        </div>
      </main>

      {/* AI Analysis Modal */}
      {showAnalysisModal && (
        <div className="fixed inset-0 z-50 overflow-y-auto" aria-labelledby="modal-title" role="dialog" aria-modal="true">
          <div className="flex items-end justify-center min-h-screen pt-4 px-4 pb-20 text-center sm:block sm:p-0">
            <div className="fixed inset-0 bg-gray-900 bg-opacity-60 backdrop-blur-md transition-opacity" onClick={() => setShowAnalysisModal(false)}></div>
            <span className="hidden sm:inline-block sm:align-middle sm:h-screen" aria-hidden="true">&#8203;</span>
            <div className="inline-block align-bottom bg-white rounded-3xl text-left overflow-hidden shadow-2xl transform transition-all sm:my-8 sm:align-middle sm:max-w-2xl sm:w-full border border-gray-100 ring-1 ring-black/5">
              <div className="bg-white px-4 pt-5 pb-4 sm:p-8">
                <div className="sm:flex sm:items-start">
                  <div className="mx-auto flex-shrink-0 flex items-center justify-center h-12 w-12 rounded-full bg-violet-50 sm:mx-0 sm:h-14 sm:w-14 ring-8 ring-violet-50/50">
                    <div className="text-violet-600">
                      <SparklesIcon />
                    </div>
                  </div>
                  <div className="mt-4 text-center sm:mt-0 sm:ml-6 sm:text-left w-full">
                    <h3 className="text-xl leading-6 font-bold text-gray-900" id="modal-title">
                      Laporan Keseluruhan Bulanan
                    </h3>
                    <div className="mt-4 text-sm text-gray-600 bg-slate-50 p-6 rounded-2xl border border-slate-100 min-h-[100px] max-h-[60vh] overflow-y-auto shadow-inner">
                      {isAnalyzing ? (
                        <div className="flex flex-col items-center justify-center py-10">
                           <div className="relative">
                             <div className="w-12 h-12 rounded-full border-4 border-violet-100 animate-spin border-t-violet-600"></div>
                           </div>
                           <p className="mt-4 font-medium text-violet-600 animate-pulse">Sedang menjana laporan cerdas...</p>
                        </div>
                      ) : (
                        <div className="prose prose-sm prose-violet max-w-none">
                           <Markdown>{analysis}</Markdown>
                        </div>
                      )}
                    </div>
                  </div>
                </div>
              </div>
              <div className="bg-gray-50 px-4 py-4 sm:px-8 sm:flex sm:flex-row-reverse">
                <Button variant="primary" onClick={() => setShowAnalysisModal(false)} disabled={isAnalyzing} className="!rounded-full">
                  Tutup
                </Button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Note Modal */}
      {noteModal.isOpen && (
        <div className="fixed inset-0 z-50 overflow-y-auto" aria-labelledby="modal-title" role="dialog" aria-modal="true">
          <div className="flex items-end justify-center min-h-screen pt-4 px-4 pb-20 text-center sm:block sm:p-0">
            <div className="fixed inset-0 bg-gray-900 bg-opacity-60 backdrop-blur-md transition-opacity" onClick={() => setNoteModal({...noteModal, isOpen: false})}></div>
            <span className="hidden sm:inline-block sm:align-middle sm:h-screen" aria-hidden="true">&#8203;</span>
            <div className="inline-block align-bottom bg-white rounded-3xl text-left overflow-hidden shadow-2xl transform transition-all sm:my-8 sm:align-middle sm:max-w-lg sm:w-full border border-gray-100 ring-1 ring-black/5">
              <div className="bg-white px-4 pt-5 pb-4 sm:p-8">
                <div className="sm:flex sm:items-start">
                  <div className="mx-auto flex-shrink-0 flex items-center justify-center h-12 w-12 rounded-full bg-blue-50 sm:mx-0 sm:h-12 sm:w-12 text-blue-600 ring-8 ring-blue-50/50">
                    <ChatBubbleIcon />
                  </div>
                  <div className="mt-3 text-center sm:mt-0 sm:ml-5 sm:text-left w-full">
                    <h3 className="text-lg leading-6 font-bold text-gray-900" id="modal-title">
                      Catatan: {new Date(noteModal.date).toLocaleDateString('ms-MY', { day: 'numeric', month: 'long', year: 'numeric' })}
                    </h3>
                    <div className="mt-4">
                      <textarea
                        className="w-full shadow-sm focus:ring-2 focus:ring-blue-500 focus:border-blue-500 block w-full text-base border-gray-200 rounded-2xl p-4 border transition-shadow bg-gray-50"
                        rows={4}
                        placeholder="Masukkan catatan anda di sini..."
                        value={noteModal.text}
                        onChange={(e) => setNoteModal({...noteModal, text: e.target.value})}
                      />
                    </div>
                  </div>
                </div>
              </div>
              <div className="bg-gray-50 px-4 py-4 sm:px-8 sm:flex sm:flex-row-reverse gap-3">
                <Button variant="primary" onClick={handleSaveNote} className="!rounded-full bg-gradient-to-r from-blue-600 to-indigo-600 hover:from-blue-700 hover:to-indigo-700">
                  Simpan
                </Button>
                <Button variant="secondary" onClick={() => setNoteModal({...noteModal, isOpen: false})} className="!rounded-full">
                  Batal
                </Button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Footer */}
      <footer className="mt-12 text-center text-white/70 text-sm pb-8 font-medium drop-shadow-md">
        <p>&copy; {new Date().getFullYear()} Sistem e-Harian.</p>
      </footer>
    </div>
  );
}

export default App;

import React from 'react';
import { PunchRecord } from '../types';

interface PunchTableProps {
  records: PunchRecord[];
  currentMonth: Date;
  onEdit: (date: string, type: 'inTime' | 'outTime', value: string) => void;
  onEditNote: (date: string, currentNote: string) => void;
}

const PencilSquareIcon = () => (
  <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z" />
  </svg>
);

const HolidayIcon = () => (
  <svg className="w-4 h-4 text-orange-500" fill="none" stroke="currentColor" viewBox="0 0 24 24" title="Hujung Minggu">
    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z" />
  </svg>
);

export const PunchTable: React.FC<PunchTableProps> = ({ records, currentMonth, onEdit, onEditNote }) => {
  // Helper to calculate duration
  const calculateDuration = (inTime: string | null, outTime: string | null) => {
    if (!inTime || !outTime) return '-';
    const [inH, inM] = inTime.split(':').map(Number);
    const [outH, outM] = outTime.split(':').map(Number);

    let diffMinutes = (outH * 60 + outM) - (inH * 60 + inM);
    if (diffMinutes < 0) return '-'; // Invalid time range

    const hours = Math.floor(diffMinutes / 60);
    const minutes = diffMinutes % 60;
    return `${hours}j ${minutes}m`;
  };

  // Helper to determine status color
  const getStatusColor = (record: PunchRecord, isWeekend: boolean) => {
    if (isWeekend) return 'bg-orange-100 text-orange-600 ring-1 ring-orange-200';
    if (record.inTime && record.outTime) return 'bg-emerald-100 text-emerald-700 ring-1 ring-emerald-200';
    if (record.inTime) return 'bg-amber-100 text-amber-700 ring-1 ring-amber-200';
    return 'bg-rose-50 text-rose-500 ring-1 ring-rose-100';
  };

  const getStatusText = (record: PunchRecord, isWeekend: boolean) => {
    if (isWeekend) return 'Cuti';
    if (record.inTime && record.outTime) return 'Lengkap';
    if (record.inTime) return 'Masuk';
    return 'Tiada';
  };

  const daysInMonth = new Date(currentMonth.getFullYear(), currentMonth.getMonth() + 1, 0).getDate();

  // Generate array of all days in month
  const allDays = Array.from({ length: daysInMonth }, (_, i) => {
    const day = i + 1;
    const dateObj = new Date(currentMonth.getFullYear(), currentMonth.getMonth(), day);
    const dateStr = `${currentMonth.getFullYear()}-${String(currentMonth.getMonth() + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
    const record = records.find(r => r.date === dateStr) || { date: dateStr, inTime: null, outTime: null, note: '' };
    // Weekend logic: Friday (5) and Saturday (6)
    const isWeekend = dateObj.getDay() === 5 || dateObj.getDay() === 6;

    // Format full date for display (e.g., 01/05/2024)
    const formattedDate = dateObj.toLocaleDateString('en-GB', {
      day: '2-digit',
      month: '2-digit',
      year: 'numeric'
    });

    return { day, dateStr, record, isWeekend, dateObj, formattedDate };
  });

  const dayNames = ['Ahad', 'Isnin', 'Selasa', 'Rabu', 'Khamis', 'Jumaat', 'Sabtu'];

  return (
    <div className="flex flex-col mt-4">

      {/* 
        MOBILE VIEW (Cards) - Visible on small screens, hidden on md and up 
      */}
      <div className="md:hidden space-y-4">
        {allDays.map(({ day, dateStr, record, isWeekend, dateObj, formattedDate }) => (
          <div key={dateStr} className={`p-4 rounded-xl border shadow-sm transition-all ${isWeekend ? 'bg-orange-50/50 border-orange-100' : 'bg-white border-gray-100'}`}>
            {/* Header: Date and Day */}
            <div className="flex justify-between items-center mb-3 pb-2 border-b border-gray-100/50">
              <span className="font-bold text-gray-700 font-mono text-sm">{formattedDate}</span>
              <div className="flex items-center gap-2">
                 <span className={`text-sm font-medium ${isWeekend ? "text-orange-600" : "text-gray-500"}`}>
                   {dayNames[dateObj.getDay()]}
                 </span>
                 {isWeekend && <HolidayIcon />}
              </div>
            </div>

            {/* Body: Inputs */}
            <div className="grid grid-cols-2 gap-3 mb-3">
              <div>
                <label className="block text-xs font-medium text-gray-400 mb-1 uppercase tracking-wider">Masuk</label>
                <input 
                  type="time" 
                  value={record.inTime || ''} 
                  onChange={(e) => onEdit(dateStr, 'inTime', e.target.value)}
                  className={`w-full border-gray-200 rounded-lg text-sm px-2 py-2 focus:ring-2 focus:ring-violet-500 focus:border-violet-500 bg-gray-50/50`}
                />
              </div>
              <div>
                <label className="block text-xs font-medium text-gray-400 mb-1 uppercase tracking-wider">Keluar</label>
                <input 
                  type="time" 
                  value={record.outTime || ''} 
                  onChange={(e) => onEdit(dateStr, 'outTime', e.target.value)}
                  className={`w-full border-gray-200 rounded-lg text-sm px-2 py-2 focus:ring-2 focus:ring-violet-500 focus:border-violet-500 bg-gray-50/50`}
                />
              </div>
            </div>

            {/* Footer: Stats & Actions */}
            <div className="flex items-center justify-between pt-1">
              <div className="flex flex-col">
                <span className="text-[10px] uppercase text-gray-400 font-bold tracking-wider">Tempoh</span>
                <span className="font-mono text-sm font-semibold text-gray-700">
                  {calculateDuration(record.inTime, record.outTime)}
                </span>
              </div>

              <div className="flex items-center gap-2">
                 <span className={`px-2 py-1 text-[10px] font-bold uppercase rounded-lg ${getStatusColor(record, isWeekend)}`}>
                    {getStatusText(record, isWeekend)}
                 </span>
                 <button
                    onClick={() => onEditNote(dateStr, record.note || '')}
                    className={`p-2 rounded-lg transition-colors ${record.note ? 'text-violet-600 bg-violet-50' : 'text-gray-400 bg-gray-50 hover:bg-gray-100'}`}
                  >
                     <PencilSquareIcon />
                  </button>
              </div>
            </div>
            {/* Note Preview if exists */}
            {record.note && (
              <div className="mt-2 pt-2 border-t border-dashed border-gray-200">
                <p className="text-xs text-gray-500 italic truncate">"{record.note}"</p>
              </div>
            )}
          </div>
        ))}
      </div>


      {/* 
        DESKTOP VIEW (Table) - Hidden on small screens, visible on md and up 
      */}
      <div className="hidden md:block -my-2 overflow-x-auto sm:-mx-6 lg:-mx-8">
        <div className="py-2 align-middle inline-block min-w-full sm:px-6 lg:px-8">
          <div className="overflow-hidden border border-gray-100 rounded-xl">
            <table className="min-w-full divide-y divide-gray-100">
              <thead className="bg-slate-50">
                <tr>
                  <th scope="col" className="px-6 py-4 text-left text-xs font-semibold text-gray-500 uppercase tracking-wider">
                    Tarikh
                  </th>
                  <th scope="col" className="px-6 py-4 text-left text-xs font-semibold text-gray-500 uppercase tracking-wider">
                    Hari
                  </th>
                  <th scope="col" className="px-6 py-4 text-left text-xs font-semibold text-gray-500 uppercase tracking-wider">
                    Masuk (IN)
                  </th>
                  <th scope="col" className="px-6 py-4 text-left text-xs font-semibold text-gray-500 uppercase tracking-wider">
                    Keluar (OUT)
                  </th>
                  <th scope="col" className="px-6 py-4 text-left text-xs font-semibold text-gray-500 uppercase tracking-wider">
                    Tempoh
                  </th>
                  <th scope="col" className="px-6 py-4 text-left text-xs font-semibold text-gray-500 uppercase tracking-wider">
                    Status
                  </th>
                  <th scope="col" className="px-6 py-4 text-left text-xs font-semibold text-gray-500 uppercase tracking-wider">
                    Catatan
                  </th>
                </tr>
              </thead>
              <tbody className="bg-white divide-y divide-gray-50">
                {allDays.map(({ day, dateStr, record, isWeekend, dateObj, formattedDate }) => (
                  <tr key={dateStr} className={isWeekend ? "bg-orange-50/40" : "hover:bg-slate-50 transition-colors"}>
                    <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-gray-700">
                      {formattedDate}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                      <div className="flex items-center gap-2">
                        <span className={isWeekend ? "font-semibold text-orange-600" : ""}>{dayNames[dateObj.getDay()]}</span>
                        {isWeekend && <HolidayIcon />}
                      </div>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                      <input 
                        type="time" 
                        value={record.inTime || ''} 
                        onChange={(e) => onEdit(dateStr, 'inTime', e.target.value)}
                        className={`border-gray-200 rounded-lg text-sm px-3 py-1.5 focus:ring-2 focus:ring-violet-500 focus:border-violet-500 transition-shadow ${isWeekend ? 'bg-white/50' : 'bg-gray-50'}`}
                        disabled={false}
                      />
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                      <input 
                        type="time" 
                        value={record.outTime || ''} 
                        onChange={(e) => onEdit(dateStr, 'outTime', e.target.value)}
                        className={`border-gray-200 rounded-lg text-sm px-3 py-1.5 focus:ring-2 focus:ring-violet-500 focus:border-violet-500 transition-shadow ${isWeekend ? 'bg-white/50' : 'bg-gray-50'}`}
                      />
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-600 font-mono">
                      {calculateDuration(record.inTime, record.outTime)}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <span className={`px-3 py-1 inline-flex text-xs leading-5 font-bold rounded-full ${getStatusColor(record, isWeekend)}`}>
                        {getStatusText(record, isWeekend)}
                      </span>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                      <button
                        onClick={() => onEditNote(dateStr, record.note || '')}
                        className="flex items-center space-x-2 text-gray-400 hover:text-violet-600 focus:outline-none group transition-colors"
                      >
                         <div className="p-1.5 rounded-md group-hover:bg-violet-50 transition-colors">
                           <PencilSquareIcon />
                         </div>
                         <span className="max-w-[120px] truncate text-xs">
                           {record.note ? <span className="text-gray-600 font-medium">{record.note}</span> : <span className="italic opacity-70">Tambah nota...</span>}
                         </span>
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useCallback } from 'react';
import { Button } from './components/Button';
import { PunchTable } from './components/PunchTable';
import { StatCard } from './components/StatCard';
import { analyzeAttendance } from './services/geminiService';
import { PunchRecord } from './types';
import Markdown from 'react-markdown';

// Icons (Updated styles)
const ClockIcon = () => <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>;
const CheckCircleIcon = () => <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>;
const CalendarIcon = () => <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg>;
const SparklesIcon = () => <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 3v4M3 5h4M6 17v4m-2-2h4m5-16l2.286 6.857L21 12l-5.714 2.143L13 21l-2.286-6.857L5 12l5.714-2.143L13 3z" /></svg>;
const DownloadIcon = () => <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>;
const ChatBubbleIcon = () => <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 10h.01M12 10h.01M16 10h.01M9 16H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-5l-5 5v-5z" /></svg>;

function App() {
  // State
  const [currentMonth, setCurrentMonth] = useState(new Date());
  const [records, setRecords] = useState<PunchRecord[]>([]);
  const [currentTime, setCurrentTime] = useState(new Date());

  // AI State
  const [analysis, setAnalysis] = useState<string | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [showAnalysisModal, setShowAnalysisModal] = useState(false);

  // Note Modal State
  const [noteModal, setNoteModal] = useState<{isOpen: boolean, date: string, text: string}>({
    isOpen: false,
    date: '',
    text: ''
  });

  // Load records from local storage on mount
  useEffect(() => {
    const saved = localStorage.getItem('punchRecords');
    if (saved) {
      try {
        setRecords(JSON.parse(saved));
      } catch (e) {
        console.error("Failed to parse records", e);
      }
    }
  }, []);

  // Save records when they change
  useEffect(() => {
    localStorage.setItem('punchRecords', JSON.stringify(records));
  }, [records]);

  // Clock Ticker
  useEffect(() => {
    const timer = setInterval(() => setCurrentTime(new Date()), 1000);
    return () => clearInterval(timer);
  }, []);

  const getTodayStr = () => currentTime.toISOString().split('T')[0];
  const getCurrentTimeStr = () => currentTime.toTimeString().slice(0, 5); // HH:mm

  // Handle Manual Edits from Table (Time and Notes)
  const handleEdit = (date: string, type: 'inTime' | 'outTime' | 'note', value: string) => {
    setRecords(prev => {
      const existingIndex = prev.findIndex(r => r.date === date);
      let newRecords = [...prev];

      if (existingIndex >= 0) {
        newRecords[existingIndex] = {
          ...newRecords[existingIndex],
          [type]: value || null
        };
      } else {
        newRecords.push({
          date: date,
          inTime: type === 'inTime' ? value : (type === 'outTime' ? null : null), // Initialize others as null
          outTime: type === 'outTime' ? value : null,
          note: type === 'note' ? value : undefined
        });
      }
      return newRecords;
    });
  };

  // Note Modal Handlers
  const handleOpenNote = (date: string, currentText: string) => {
    setNoteModal({ isOpen: true, date, text: currentText || '' });
  };

  const handleSaveNote = () => {
    handleEdit(noteModal.date, 'note', noteModal.text);
    setNoteModal({ ...noteModal, isOpen: false });
  };

  // Month Navigation
  const changeMonth = (offset: number) => {
    const newDate = new Date(currentMonth.getFullYear(), currentMonth.getMonth() + offset, 1);
    setCurrentMonth(newDate);
  };

  // Filter records for current month only
  const getMonthRecords = () => {
    const year = currentMonth.getFullYear();
    const month = currentMonth.getMonth() + 1;
    return records.filter(r => {
      const [rYear, rMonth] = r.date.split('-').map(Number);
      return rYear === year && rMonth === month;
    });
  };

  // Calculate Total Hours for the month
  const calculateTotalMonthHours = () => {
    const monthRecords = getMonthRecords();
    let totalMinutes = 0;

    monthRecords.forEach(record => {
      if (record.inTime && record.outTime) {
        const [inH, inM] = record.inTime.split(':').map(Number);
        const [outH, outM] = record.outTime.split(':').map(Number);

        const diff = (outH * 60 + outM) - (inH * 60 + inM);
        if (diff > 0) {
          totalMinutes += diff;
        }
      }
    });

    const hours = Math.floor(totalMinutes / 60);
    const minutes = totalMinutes % 60;

    return `${hours}j ${minutes}m`;
  };

  // Export CSV Handler
  const handleExportCSV = () => {
    const year = currentMonth.getFullYear();
    const month = currentMonth.getMonth();
    const daysInMonth = new Date(year, month + 1, 0).getDate();
    const monthName = currentMonth.toLocaleDateString('ms-MY', { month: 'long', year: 'numeric' });

    const headers = ['Tarikh', 'Hari', 'Masuk (IN)', 'Keluar (OUT)', 'Tempoh', 'Status', 'Catatan'];
    let csvContent = headers.join(',') + '\n';

    for (let i = 1; i <= daysInMonth; i++) {
      const dateObj = new Date(year, month, i);
      const dateStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(i).padStart(2, '0')}`;
      const record = records.find(r => r.date === dateStr) || { date: dateStr, inTime: null, outTime: null, note: '' };

      const formattedDate = dateObj.toLocaleDateString('en-GB', { day: '2-digit', month: '2-digit', year: 'numeric' });
      const dayName = dateObj.toLocaleDateString('ms-MY', { weekday: 'long' });

      // Changed weekend logic: Friday (5) and Saturday (6) are weekends
      const isWeekend = dateObj.getDay() === 5 || dateObj.getDay() === 6;

      // Calculate Status (Replicating PunchTable logic for consistency)
      let status = 'Tiada';
      if (isWeekend) status = 'Cuti';
      else if (record.inTime && record.outTime) status = 'Lengkap';
      else if (record.inTime) status = 'Masuk';

      // Calculate Duration
      let duration = '-';
      if (record.inTime && record.outTime) {
        const [inH, inM] = record.inTime.split(':').map(Number);
        const [outH, outM] = record.outTime.split(':').map(Number);
        let diffMinutes = (outH * 60 + outM) - (inH * 60 + inM);

        if (diffMinutes >= 0) {
          const hours = Math.floor(diffMinutes / 60);
          const minutes = diffMinutes % 60;
          duration = `${hours}j ${minutes}m`;
        }
      }

      // Safe CSV string escaping
      const escapeCsv = (str: string | null | undefined) => {
        if (!str) return '""';
        return `"${str.replace(/"/g, '""')}"`;
      };

      const row = [
        formattedDate,
        dayName,
        record.inTime || '',
        record.outTime || '',
        duration,
        status,
        record.note || ''
      ].map(field => escapeCsv(field)).join(',');

      csvContent += row + '\n';
    }

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    if (link.download !== undefined) {
      const url = URL.createObjectURL(blob);
      link.setAttribute('href', url);
      link.setAttribute('download', `Laporan_Kehadiran_${monthName.replace(/\s+/g, '_')}.csv`);
      link.style.visibility = 'hidden';
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
    }
  };

  // AI Analysis Handler
  const handleAnalyze = async () => {
    setIsAnalyzing(true);
    setShowAnalysisModal(true);

    const monthName = currentMonth.toLocaleDateString('ms-MY', { month: 'long', year: 'numeric' });
    const result = await analyzeAttendance(getMonthRecords(), monthName);

    setAnalysis(result);
    setIsAnalyzing(false);
  };

  return (
    <div 
      className="min-h-screen pb-12 bg-cover bg-center bg-fixed bg-no-repeat font-sans"
      style={{
        backgroundImage: `url('https://images.unsplash.com/photo-1620641788421-7f1c91ade639?q=80&w=2560&auto=format&fit=crop')` // Stunning Seamless Gradient
      }}
    >
      {/* 
         Unified Header Concept: 
      */}
      <header className="pt-6 sm:pt-8 pb-24 sm:pb-32 relative z-10">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex flex-col md:flex-row items-center justify-between gap-4 sm:gap-6">

            {/* Logo / Title Area */}
            <div className="w-full md:w-auto bg-white/10 backdrop-blur-md border border-white/20 rounded-2xl p-4 shadow-xl flex items-center justify-center md:justify-start gap-4 hover:bg-white/15 transition-colors duration-300">
               <div className="bg-gradient-to-br from-violet-500 to-fuchsia-500 p-3 rounded-xl shadow-lg">
                 <CalendarIcon />
               </div>
               <div className="text-left">
                  <h1 className="text-2xl font-bold text-white tracking-tight drop-shadow-sm leading-none">e-Harian</h1>
                  <span className="text-xs text-blue-100 font-medium tracking-wider uppercase">Sistem Kehadiran</span>
               </div>
            </div>

            {/* Clock Area */}
            <div className="w-full md:w-auto flex flex-col items-center md:items-end">
               <div className="w-full md:w-auto bg-black/20 backdrop-blur-md rounded-2xl px-6 py-3 border border-white/10 shadow-lg text-white">
                  <div className="text-xs font-medium text-blue-200 uppercase tracking-widest text-center mb-1">
                    {currentTime.toLocaleDateString('ms-MY', { weekday: 'long', day: 'numeric', month: 'long' })}
                  </div>
                  <div className="text-4xl font-mono font-bold tracking-wider drop-shadow-lg text-center">
                    {currentTime.toLocaleTimeString('ms-MY')}
                  </div>
               </div>
            </div>

          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 -mt-20 sm:-mt-24 relative z-20">
        {/* Status Cards / Actions */}
        <div className="mb-6 sm:mb-8 transform transition-all hover:scale-[1.01] duration-300">
          {/* Stats Card - Enhanced Glassmorphism */}
          <StatCard 
            title="Jumlah Jam (Bulan Ini)"
            value={calculateTotalMonthHours()}
            icon={<ClockIcon />}
            colorClass="bg-gradient-to-br from-cyan-400 to-blue-500 text-white shadow-lg"
          />
        </div>

        {/* Month Navigation & Table - Glassmorphism Effect */}
        <div className="bg-white/90 backdrop-blur-lg shadow-2xl shadow-black/5 rounded-3xl p-1 border border-white/60">
           <div className="bg-white/50 rounded-[1.4rem] p-4 sm:p-6">
              <div className="flex flex-col xl:flex-row items-center justify-between mb-6 sm:mb-8 gap-4">
                {/* Left: Spacer (Hidden on mobile) */}
                <div className="hidden xl:block xl:w-1/3"></div>

                {/* Center: Month Navigation */}
                <div className="w-full xl:w-1/3 flex items-center justify-between sm:justify-center space-x-2 sm:space-x-6 bg-white p-2 rounded-xl sm:rounded-full border border-gray-100 shadow-sm">
                    <button onClick={() => changeMonth(-1)} className="p-2 sm:p-2.5 hover:bg-gray-50 rounded-full transition-all text-gray-400 hover:text-violet-600">
                      <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M15 19l-7-7 7-7" /></svg>
                    </button>
                    <h2 className="text-base sm:text-lg font-bold text-gray-800 uppercase tracking-wide whitespace-nowrap min-w-[120px] sm:min-w-[150px] text-center">
                      {currentMonth.toLocaleDateString('ms-MY', { month: 'long', year: 'numeric' })}
                    </h2>
                    <button onClick={() => changeMonth(1)} className="p-2 sm:p-2.5 hover:bg-gray-50 rounded-full transition-all text-gray-400 hover:text-violet-600">
                      <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M9 5l7 7-7 7" /></svg>
                    </button>
                </div>

                {/* Right: Actions */}
                <div className="flex flex-row justify-center sm:justify-end xl:w-1/3 w-full gap-2">
                    <Button 
                      variant="primary" 
                      onClick={handleAnalyze} 
                      className="flex-1 sm:flex-none !px-4 flex items-center justify-center !rounded-xl sm:!rounded-full shadow-lg shadow-violet-500/30" 
                      title="Analisa Prestasi (AI)"
                    >
                      <SparklesIcon />
                    </Button>

                    <Button variant="secondary" onClick={handleExportCSV} className="flex-1 sm:flex-none flex items-center justify-center gap-2 border-gray-200 !rounded-xl sm:!rounded-full hover:bg-gray-50" title="Muat Turun CSV">
                      <DownloadIcon />
                      <span>CSV</span>
                    </Button>
                </div>
              </div>

              <PunchTable 
                records={records} 
                currentMonth={currentMonth}
                onEdit={handleEdit}
                onEditNote={handleOpenNote}
              />
           </div>
        </div>
      </main>

      {/* AI Analysis Modal */}
      {showAnalysisModal && (
        <div className="fixed inset-0 z-50 overflow-y-auto" aria-labelledby="modal-title" role="dialog" aria-modal="true">
          <div className="flex items-end justify-center min-h-screen pt-4 px-4 pb-20 text-center sm:block sm:p-0">
            <div className="fixed inset-0 bg-gray-900 bg-opacity-60 backdrop-blur-md transition-opacity" onClick={() => setShowAnalysisModal(false)}></div>
            <span className="hidden sm:inline-block sm:align-middle sm:h-screen" aria-hidden="true">&#8203;</span>
            <div className="inline-block align-bottom bg-white rounded-3xl text-left overflow-hidden shadow-2xl transform transition-all sm:my-8 sm:align-middle sm:max-w-2xl sm:w-full border border-gray-100 ring-1 ring-black/5">
              <div className="bg-white px-4 pt-5 pb-4 sm:p-8">
                <div className="sm:flex sm:items-start">
                  <div className="mx-auto flex-shrink-0 flex items-center justify-center h-12 w-12 rounded-full bg-violet-50 sm:mx-0 sm:h-14 sm:w-14 ring-8 ring-violet-50/50">
                    <div className="text-violet-600">
                      <SparklesIcon />
                    </div>
                  </div>
                  <div className="mt-4 text-center sm:mt-0 sm:ml-6 sm:text-left w-full">
                    <h3 className="text-xl leading-6 font-bold text-gray-900" id="modal-title">
                      Laporan Keseluruhan Bulanan
                    </h3>
                    <div className="mt-4 text-sm text-gray-600 bg-slate-50 p-6 rounded-2xl border border-slate-100 min-h-[100px] max-h-[60vh] overflow-y-auto shadow-inner">
                      {isAnalyzing ? (
                        <div className="flex flex-col items-center justify-center py-10">
                           <div className="relative">
                             <div className="w-12 h-12 rounded-full border-4 border-violet-100 animate-spin border-t-violet-600"></div>
                           </div>
                           <p className="mt-4 font-medium text-violet-600 animate-pulse">Sedang menjana laporan cerdas...</p>
                        </div>
                      ) : (
                        <div className="prose prose-sm prose-violet max-w-none">
                           <Markdown>{analysis}</Markdown>
                        </div>
                      )}
                    </div>
                  </div>
                </div>
              </div>
              <div className="bg-gray-50 px-4 py-4 sm:px-8 sm:flex sm:flex-row-reverse">
                <Button variant="primary" onClick={() => setShowAnalysisModal(false)} disabled={isAnalyzing} className="!rounded-full w-full sm:w-auto">
                  Tutup
                </Button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Note Modal */}
      {noteModal.isOpen && (
        <div className="fixed inset-0 z-50 overflow-y-auto" aria-labelledby="modal-title" role="dialog" aria-modal="true">
          <div className="flex items-end justify-center min-h-screen pt-4 px-4 pb-20 text-center sm:block sm:p-0">
            <div className="fixed inset-0 bg-gray-900 bg-opacity-60 backdrop-blur-md transition-opacity" onClick={() => setNoteModal({...noteModal, isOpen: false})}></div>
            <span className="hidden sm:inline-block sm:align-middle sm:h-screen" aria-hidden="true">&#8203;</span>
            <div className="inline-block align-bottom bg-white rounded-3xl text-left overflow-hidden shadow-2xl transform transition-all sm:my-8 sm:align-middle sm:max-w-lg sm:w-full border border-gray-100 ring-1 ring-black/5">
              <div className="bg-white px-4 pt-5 pb-4 sm:p-8">
                <div className="sm:flex sm:items-start">
                  <div className="mx-auto flex-shrink-0 flex items-center justify-center h-12 w-12 rounded-full bg-blue-50 sm:mx-0 sm:h-12 sm:w-12 text-blue-600 ring-8 ring-blue-50/50">
                    <ChatBubbleIcon />
                  </div>
                  <div className="mt-3 text-center sm:mt-0 sm:ml-5 sm:text-left w-full">
                    <h3 className="text-lg leading-6 font-bold text-gray-900" id="modal-title">
                      Catatan: {new Date(noteModal.date).toLocaleDateString('ms-MY', { day: 'numeric', month: 'long', year: 'numeric' })}
                    </h3>
                    <div className="mt-4">
                      <textarea
                        className="w-full shadow-sm focus:ring-2 focus:ring-blue-500 focus:border-blue-500 block w-full text-base border-gray-200 rounded-2xl p-4 border transition-shadow bg-gray-50"
                        rows={4}
                        placeholder="Masukkan catatan anda di sini..."
                        value={noteModal.text}
                        onChange={(e) => setNoteModal({...noteModal, text: e.target.value})}
                      />
                    </div>
                  </div>
                </div>
              </div>
              <div className="bg-gray-50 px-4 py-4 sm:px-8 sm:flex sm:flex-row-reverse gap-3 flex-col sm:flex-row">
                <Button variant="primary" onClick={handleSaveNote} className="!rounded-full bg-gradient-to-r from-blue-600 to-indigo-600 hover:from-blue-700 hover:to-indigo-700 w-full sm:w-auto">
                  Simpan
                </Button>
                <Button variant="secondary" onClick={() => setNoteModal({...noteModal, isOpen: false})} className="!rounded-full w-full sm:w-auto">
                  Batal
                </Button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Footer */}
      <footer className="mt-12 text-center text-white/70 text-sm pb-8 font-medium drop-shadow-md">
        <p>&copy; {new Date().getFullYear()} Sistem e-Harian.</p>
      </footer>
    </div>
  );
}

export default App;

import React, { useState, useEffect, useCallback } from 'react';
import { Button } from './components/Button';
import { PunchTable } from './components/PunchTable';
import { StatCard } from './components/StatCard';
import { analyzeAttendance } from './services/geminiService';
import { PunchRecord } from './types';
import Markdown from 'react-markdown';
import { jsPDF } from 'jspdf';
import autoTable from 'jspdf-autotable';

// Icons (Updated styles)
const ClockIcon = () => <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>;
const CheckCircleIcon = () => <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>;
const CalendarIcon = () => <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg>;
